css:
/* ==========================================================================
   海报墙 · Folia Poster Wall
   1:1 复刻 Folia（folia-major）的主题语言，不再迁就 MyTranscript 的骨架：
   近黑底 + 双色光晕 + 胶片噪点 + 无缝海报瓦片 + 悬浮胶囊播放条。
   取值全部来自 Folia 安装包内 CSS（Lattice / wall / BravaisStage）。
   ========================================================================== */

html[data-theme] {
  --bg: #070708;
  --ink: #f7f4ee;
  --bright: #ffffff;
  --muted: rgba(247, 244, 238, 0.62);
  --dim: rgba(247, 244, 238, 0.38);
  --accent: #fd5c47;
  --accent2: #6a48ff;
  --accent-ink: #fd5c47;
  --panel: rgba(255, 255, 255, 0.045);
  --panel2: rgba(255, 255, 255, 0.07);
  --hover: rgba(255, 255, 255, 0.06);
  --line: rgba(255, 255, 255, 0.10);
  --line2: rgba(255, 255, 255, 0.055);
  --coverbg: #101014;
  --serif: system-ui, -apple-system, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
  --sans: system-ui, -apple-system, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
  --mono: ui-monospace, "SF Mono", Consolas, monospace;
  --ease: cubic-bezier(0.22, 0.61, 0.36, 1);
  /* 侧栏 / 搜索胶囊 / 悬浮底栏共用一层烟熏玻璃：同色、同模糊、同描边。 */
  --folia-glass: rgba(18, 18, 20, 0.62);
  --folia-glass-line: rgba(255, 255, 255, 0.10);
  --folia-glass-blur: blur(18px) saturate(1.1);
  --folia-glass-shadow: 0 24px 60px rgba(0, 0, 0, 0.52);
  /* 字幕页不再用纯黑：暖炭底 + 顶部一点专辑色余温，和珊瑚主色同一族 */
  --folia-player-bg: #0d0b09;
  --folia-player-glow: #2a1a12;
}

/* ---------- 0. 画布：底色 + 两团光晕 + 噪点 + 暗角 ---------- */
html[data-theme] body,
html[data-theme] .app {
  background: var(--bg);
  color: var(--ink);
  font-family: var(--sans);
}

html[data-theme] body::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background:
    radial-gradient(circle at 14% 12%, color-mix(in srgb, var(--accent) 16%, transparent), transparent 29%),
    radial-gradient(circle at 86% 82%, color-mix(in srgb, var(--accent2) 20%, transparent), transparent 32%);
}

html[data-theme] body::after {
  content: "";
  position: fixed;
  inset: 0;
  z-index: 9999;
  pointer-events: none;
  opacity: 0.13;
  mix-blend-mode: soft-light;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.92' numOctaves='2' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.55'/%3E%3C/svg%3E");
}

html[data-theme] .app {
  background:
    radial-gradient(circle at 14% 12%, color-mix(in srgb, var(--accent) 16%, transparent), transparent 29%),
    radial-gradient(circle at 86% 82%, color-mix(in srgb, var(--accent2) 20%, transparent), transparent 32%),
    var(--bg);
  box-shadow: inset 0 0 120px 40px rgba(0, 0, 0, 0.55);
}

/* ---------- 1. 骨架：侧栏整条隐藏，只留一个悬浮钮 ---------- */
html[data-theme] .app { display: block; }

/* 侧栏 = 贴在左缘、垂直居中的圆角浮条（不是通高柱子） */
html[data-theme] .sidebar {
  position: fixed;
  left: 14px;
  top: 50%;
  bottom: auto;
  width: 64px;
  height: auto;
  max-height: 82vh;
  z-index: 70;
  padding: 10px 7px;
  border: 1px solid var(--folia-glass-line);
  border-radius: 22px;
  background: var(--folia-glass);
  box-shadow: var(--folia-glass-shadow), inset 0 1px 0 rgba(255, 255, 255, 0.08);
  backdrop-filter: var(--folia-glass-blur);
  -webkit-backdrop-filter: var(--folia-glass-blur);
  overflow: auto;
  scrollbar-width: none;
  transform: translate(-120%, -50%);
  opacity: 0;
  pointer-events: none;
  transition: width var(--motion-slow) var(--ease), height var(--motion-slow) var(--ease),
    left var(--motion-slow) var(--ease), padding var(--motion-slow) var(--ease),
    border-radius var(--motion-slow) var(--ease), transform var(--motion-slow) var(--ease),
    opacity var(--motion-slow) var(--ease);
}
html[data-theme] .sidebar::-webkit-scrollbar { width: 0; height: 0; }
/* 默认收起；点悬浮钮展开（body 去掉 nav-collapsed）就滑出这支浮条 */
html[data-theme] body:not(.nav-collapsed) .sidebar {
  display: flex;
  transform: translate(0, -50%);
  opacity: 1;
  pointer-events: auto;
}

html[data-theme] .brand {
  justify-content: center;
  gap: 0;
  padding: 2px 0 8px;
}
html[data-theme] .brand > div:not(.brand-mark) { display: none; }
html[data-theme] .brand-name,
html[data-theme] .brand-sub,
html[data-theme] .nav-label,
html[data-theme] .sidebar-add,
html[data-theme] .mobile-more-close,
html[data-theme] .plugin-slot,
html[data-theme] #pluginNavLabel,
html[data-theme] #pluginNav { display: none !important; }

html[data-theme] .brand-mark {
  width: 34px;
  height: 34px;
  border: 1px solid rgba(255, 255, 255, 0.10);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.06);
  color: var(--ink);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08);
}
html[data-theme] .brand-mark svg { width: 16px; height: 16px; fill: none; stroke: var(--ink); }

html[data-theme] .nav {
  display: flex;
  flex-direction: column;
  gap: 3px;
  align-items: center;
}
/* 两组导航之间用一道极淡的分隔线断开，不再是一根没有呼吸的图标柱子 */
html[data-theme] #sideNav2 {
  margin-top: 7px;
  padding-top: 7px;
  border-top: 1px solid rgba(255, 255, 255, 0.07);
}

html[data-theme] .nav button {
  width: 38px;
  height: 38px;
  padding: 0;
  border: 0;
  border-radius: 999px;
  justify-content: center;
  font-size: 0;
  color: rgba(247, 244, 238, 0.60);
  background: transparent;
  transition: background-color var(--motion-normal) var(--ease), color var(--motion-normal) var(--ease), scale var(--motion-fast) var(--ease);
}
html[data-theme] .nav button:hover { background: rgba(255, 255, 255, 0.08); color: var(--ink); }
html[data-theme] .nav button:hover svg { scale: 1.06; }
html[data-theme] .nav button svg { transition: scale var(--motion-fast) var(--ease); }
/* 图标栏只剩图标：悬停时从右侧浮出功能名（Folia 的 rail tooltip） */
html[data-theme] .sidebar { overflow: visible; }
html[data-theme] .sidebar .nav button { position: relative; }
html[data-theme] .sidebar .nav button::after {
  content: attr(data-label);
  position: absolute;
  left: calc(100% + 12px);
  top: 50%;
  translate: -4px -50%;
  padding: 7px 11px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 10px;
  background: rgba(10, 10, 12, 0.92);
  box-shadow: 0 10px 26px rgba(0, 0, 0, 0.5);
  backdrop-filter: blur(10px);
  color: var(--ink);
  font: 700 11px/1 var(--sans);
  letter-spacing: 0.04em;
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--motion-fast) var(--ease), translate var(--motion-fast) var(--ease);
}
html[data-theme] .sidebar .nav button:hover::after,
html[data-theme] .sidebar .nav button:focus::after,
html[data-theme] .sidebar .nav button:focus-visible::after {
  opacity: 1;
  translate: 0 -50%;
}
html[data-theme] .nav button.active,
html[data-theme] .nav button[aria-current="page"] {
  border: 0;
  outline: 0;
  background: color-mix(in srgb, var(--accent) 18%, transparent);
  color: var(--bright);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 34%, transparent);
}
html[data-theme] .nav .nav-ico,
html[data-theme] .nav button svg {
  width: 15px;
  height: 15px;
  flex: 0 0 15px;
  padding: 0;
  border-radius: 0;
  background: transparent !important;
}
html[data-theme] .nav button:hover .nav-ico { background: transparent !important; }

html[data-theme] .sidebar-bottom { display: none; }

/* ---------- 2. 顶栏：平时看不见，鼠标贴到屏幕顶端才浮出来 ---------- */
html[data-theme] .main {
  padding: 0 0 110px;
  height: 100vh;
  overflow: auto;
  scroll-padding-top: 20px;
}
/* 基础层的 .page 有 1480px 上限并在大屏居中，全屏后两侧就留出黑边；墙要一路铺到窗口边缘 */
html[data-theme] .page {
  max-width: none;
  margin: 0;
}
/* 播放中的那张小播放条和底栏会同时出现（两条底栏），主题里只留一条 */
html[data-theme] .mini-player { display: none !important; }

/* 顶端 18px 是感应区；贴上去才显示右侧两个圆钮 */
html[data-theme] .topbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: 18px;
  padding: 0;
  margin: 0;
  border: 0;
  background: transparent;
  backdrop-filter: none;
  justify-content: flex-end;
  align-items: flex-start;
  overflow: visible;
  pointer-events: auto;
  z-index: 92;
}
html[data-theme] .topbar:hover { height: 62px; }

html[data-theme] .topbar .crumb { display: contents; }
html[data-theme] .topbar .crumb b { display: none; }
/* Folia 的侧栏常驻，用自动隐藏和左缘唤回就够了，不再保留手动收起钮。 */
html[data-theme] .topbar .rail-toggle { display: none; }

html[data-theme] .topbar .top-actions {
  position: absolute;
  top: 12px;
  right: 14px;
  gap: 8px;
  opacity: 0;
  transform: translateY(-6px);
  transition: opacity var(--motion-slow) var(--ease), transform var(--motion-slow) var(--ease);
  pointer-events: none;
}
html[data-theme] .topbar:hover .top-actions,
html[data-theme] .topbar .top-actions:focus-within {
  opacity: 1;
  transform: none;
  pointer-events: auto;
}
html[data-theme] .top-actions > button,
html[data-theme] .top-actions .btn {
  width: 40px;
  height: 40px;
  min-width: 40px;
  padding: 0;
  border: 0;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
  color: var(--ink);
  display: grid;
  place-items: center;
  font-size: 0;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.24);
  backdrop-filter: blur(8px);
}
html[data-theme] .top-actions > button:hover { background: rgba(255, 255, 255, 0.14); }
html[data-theme] .top-actions svg,
html[data-theme] .top-actions .btn-ico { width: 16px; height: 16px; }

/* ---------- 3. 首页：只剩一面墙 ---------- */
html[data-theme] .ledger-home {
  max-width: none;
  margin: 0;
  padding: 0;
}

html[data-theme] .ledger-home .ledger-mast {
  display: block;
  padding: 0;
  margin: 0;
  border: 0;
}
html[data-theme] .ledger-home .ledger-mast-copy { display: contents; }
html[data-theme] .ledger-home .ledger-mast-copy > .eyebrow,
html[data-theme] .ledger-home .ledger-mast-copy > h1,
html[data-theme] .ledger-home .ledger-mast-copy > p,
html[data-theme] .ledger-home .ledger-editor,
html[data-theme] .ledger-home .ledger-rule,
html[data-theme] .ledger-home .ledger-section,
html[data-theme] .ledger-home #homeContinue,
html[data-theme] .ledger-home #homeRecent,
html[data-theme] .ledger-home #homeStats,
html[data-theme] .ledger-home .home-onboard { display: none !important; }
/* 推荐墙本身就是首页：包着 #homeRecommended 的那一节必须留着，
   其余 ledger 分节（继续收听 / 最近更新 / 统计）全部让位。 */
html[data-theme] .ledger-home .ledger-section:has(#homeRecommended) { display: block !important; }
html[data-theme] .ledger-home .ledger-section:has(#homeRecommended) > h3,
html[data-theme] .ledger-home .ledger-section:has(#homeRecommended) > small { display: none !important; }

/* 搜索：Folia 顶部悬浮胶囊 */
html[data-theme] .ledger-search {
  position: fixed;
  z-index: 40;
  top: 14px;
  left: 50%;
  transform: translateX(-50%);
  width: min(520px, 52vw);
  max-width: none;
  height: 42px;
  padding: 0 6px 0 16px;
  gap: 8px;
  border: 1px solid var(--folia-glass-line);
  border-radius: 999px;
  background: var(--folia-glass);
  backdrop-filter: var(--folia-glass-blur);
  -webkit-backdrop-filter: var(--folia-glass-blur);
  box-shadow: var(--folia-glass-shadow);
  opacity: 1;
  translate: 0 0;
  transition: opacity var(--motion-normal) var(--ease), translate var(--motion-normal) var(--ease),
    top var(--motion-slow) var(--ease),
    width var(--motion-slow) var(--ease), height var(--motion-slow) var(--ease),
    padding var(--motion-slow) var(--ease), background-color var(--motion-fast) var(--ease);
}
html[data-theme] .ledger-search span { color: rgba(247, 244, 238, 0.5); display: grid; place-items: center; }
html[data-theme] .ledger-search input {
  font: 500 13.5px/1 var(--sans);
  color: var(--ink);
  letter-spacing: 0.01em;
}
html[data-theme] .ledger-search input::placeholder { color: rgba(247, 244, 238, 0.42); }
html[data-theme] .ledger-search button {
  width: 32px;
  height: 32px;
  border: 0;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.10);
  color: var(--ink);
}
html[data-theme] .ledger-search button:hover { background: var(--accent); color: #fff; }

/* ---------- 4. 海报墙：大小混排、无缝、无边框 ---------- */
/* 首页整页就是墙：不留左右白，瓦片一路铺到屏幕边缘，往下滚不完 */
html[data-theme] #page-home { padding: 0; }

/* 二维墙：三块同宽 12 栏块并排；横向位置由 JS 的 --folia-block-w / left 控制，
   镜头用 .main 的 scrollLeft，走到边上时整列倒到另一头，实现 Folia 的横向无限。 */
html[data-theme] .folia-wall-plane {
  position: relative;
  width: calc(var(--folia-block-w, 100vw) * 3);
  margin: 0;
  padding: 0;
}
html[data-theme] .folia-wall-plane > #homeRecommended {
  position: absolute;
  top: 0;
  width: var(--folia-block-w, 100vw);
  margin: 0;
}

html[data-theme] #homeRecommended {
  counter-reset: folia-poster;
  container-type: inline-size;
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  grid-auto-rows: calc((100cqw - 22px) / 12);
  grid-auto-flow: dense;
  gap: 2px;
  margin: 0;
  padding: 0 0 128px;   /* 顶上不留黑边：第一排瓦片直接接到窗口顶，顶栏浮在上面 */
  height: auto;
  background: transparent;
}
/* 无限墙 = Folia 的 12×8 方块格：一格 = 一个正方 cell，瓦片按格数跨列跨行
   （3×2 / 6×4 / 3×4 / 4×4 / 2×2 混排，取自 wall/blockTemplates 的变体 0） */
html[data-theme] #homeRecommended .pod-card { grid-column: span 3; grid-row: span 2; }
/* 铺满周期 = 14 块：12 席整块（3x2 / 6x4 / 3x2 / 3x2 / 3x4 / 4x4 / 2x2 / 3x2 / 2x2×4）+ 收尾两块 6x4 把第二个 12×8 块填满。
   无限补块时每加 14 块正好接上同样的两块，所以变体按 14n 取模。 */
html[data-theme] #homeRecommended .pod-card:nth-child(14n + 1) { grid-column: span 3; grid-row: span 2; }
html[data-theme] #homeRecommended .pod-card:nth-child(14n + 2) { grid-column: span 6; grid-row: span 4; }
html[data-theme] #homeRecommended .pod-card:nth-child(14n + 3) { grid-column: span 3; grid-row: span 2; }
html[data-theme] #homeRecommended .pod-card:nth-child(14n + 4) { grid-column: span 3; grid-row: span 2; }
html[data-theme] #homeRecommended .pod-card:nth-child(14n + 5) { grid-column: span 3; grid-row: span 4; }
html[data-theme] #homeRecommended .pod-card:nth-child(14n + 6) { grid-column: span 4; grid-row: span 4; }
html[data-theme] #homeRecommended .pod-card:nth-child(14n + 7) { grid-column: span 2; grid-row: span 2; }
html[data-theme] #homeRecommended .pod-card:nth-child(14n + 8) { grid-column: span 3; grid-row: span 2; }
html[data-theme] #homeRecommended .pod-card:nth-child(14n + 9),
html[data-theme] #homeRecommended .pod-card:nth-child(14n + 10),
html[data-theme] #homeRecommended .pod-card:nth-child(14n + 11),
html[data-theme] #homeRecommended .pod-card:nth-child(14n + 12) { grid-column: span 2; grid-row: span 2; }
html[data-theme] #homeRecommended .pod-card:nth-child(14n + 13),
html[data-theme] #homeRecommended .pod-card:nth-child(14n + 14) { grid-column: span 6; grid-row: span 4; }

html[data-theme] .pod-grid { gap: 2px; }

html[data-theme] .pod-card {
  position: relative;
  display: block;
  overflow: hidden;
  padding: 0;
  border: 0;
  border-radius: 0;
  aspect-ratio: auto;
  height: 100%;
  min-height: 0;
  background: var(--coverbg);
  color: var(--ink);
  counter-increment: folia-poster;
  box-shadow: none;
  isolation: isolate;
  transition: filter var(--motion-slow) var(--ease), box-shadow var(--motion-slow) var(--ease);
}

html[data-theme] .pod-card-main {
  position: absolute;
  inset: 0;
  z-index: auto;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  gap: 5px;
  padding: 24px;
  color: inherit;
  text-decoration: none;
}

html[data-theme] .pod-card .pod-art {
  position: absolute;
  inset: 0;
  z-index: 0;
  width: 100%;
  height: 100%;
  aspect-ratio: auto;
  border: 0;
  border-radius: 0;
  background: var(--coverbg);
  outline: 0;
}
html[data-theme] .pod-card .pod-art img { width: 100%; height: 100%; object-fit: cover; }
html[data-theme] .pod-card .pod-art span {
  font-size: 34px;
  font-weight: 800;
  letter-spacing: -0.04em;
  color: rgba(255, 255, 255, 0.8);
}

/* 压字黑幕：Folia 的 5% / 24% / 92% 三段 */
html[data-theme] .pod-card::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  background: linear-gradient(180deg,
    rgba(0, 0, 0, 0.05) 34%,
    rgba(0, 0, 0, 0.24) 56%,
    rgba(0, 0, 0, 0.92) 100%);
}

html[data-theme] .pod-card .pod-card-main > strong {
  position: relative;
  z-index: 2;
  margin-block: -0.14em;
  padding-block: 0.14em;
  font-size: clamp(26px, 2.6vw, 46px);
  line-height: 0.96;
  font-weight: 800;
  letter-spacing: -0.045em;
  color: var(--ink);
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
  text-wrap: balance;
}

html[data-theme] .pod-card .pod-meta {
  position: relative;
  z-index: 2;
  font-size: 13px;
  font-weight: 650;
  letter-spacing: 0.01em;
  color: rgba(247, 244, 238, 0.78);
  white-space: nowrap;
  text-overflow: ellipsis;
  overflow: hidden;
}

html[data-theme] .pod-card .pod-name {
  position: relative;
  z-index: 2;
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--accent);
}
html[data-theme] .pod-card .pod-latest,
html[data-theme] .pod-card .pod-badges,
html[data-theme] .pod-card .pod-actions { display: none !important; }
html[data-theme] .pod-card .pod-desc { display: none !important; }

/* 角标编号 */
html[data-theme] .pod-card::before {
  content: counter(folia-poster, decimal-leading-zero);
  position: absolute;
  z-index: 3;
  top: 14px;
  left: 14px;
  padding: 5px 8px;
  border: 0;
  border-radius: 0;
  background: rgba(0, 0, 0, 0.62);
  color: rgba(255, 255, 255, 0.92);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.12em;
  font-variant-numeric: tabular-nums;
}

html[data-theme] #homeRecommended .pod-card:hover { filter: saturate(1.08) brightness(1.05); z-index: 3; }
html[data-theme] .pod-card:hover { filter: saturate(1.08) brightness(1.05); z-index: 3; }
/* 按下 / 悬停的微动效：Folia 的封面是会呼吸的，不是死图 */
html[data-theme] #homeRecommended .pod-card { transition: filter var(--motion-slow) var(--ease), box-shadow var(--motion-slow) var(--ease), scale var(--motion-fast) var(--ease); }
html[data-theme] #homeRecommended .pod-card:active { scale: 0.985; }
