}
html[data-theme] #homeRecommended .pod-card:hover .pod-art img { transform: scale(1.035); }
html[data-theme] #homeRecommended .pod-card .pod-card-main > strong { transition: font-size var(--motion-slow) var(--ease), color var(--motion-slow) var(--ease); }

/* Folia 的“正在播放”：瓦片里压一圈珊瑚描边 + 角标点亮 + 右下小胶囊 */
html[data-theme] .pod-card.is-playing-tile {
  z-index: 2;
