html[data-theme] .pod-card.is-playing-tile-live::before { animation: foliaBadgePulse 1.6s var(--ease) infinite; }
@keyframes foliaBadgePulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.62; }
}

/* 每格字号按格子大小定，小方格不顶字（尺寸来自 Folia 12×8 格子）。
   Folia 的 201px 小瓦片标题约 23.6px，这里不再压到 14–19px。 */
html[data-theme] #homeRecommended .pod-card .pod-card-main { padding: 14px 14px 15px; }
html[data-theme] #homeRecommended .pod-card .pod-card-main > strong { font-size: clamp(26px, 2.6vw, 46px); -webkit-line-clamp: 2; }
html[data-theme] #homeRecommended .pod-card .pod-meta { font-size: 11.5px; }

/* 2×2 小方格：字再收一号 */
html[data-theme] #homeRecommended .pod-card:nth-child(14n + 7) .pod-card-main,
html[data-theme] #homeRecommended .pod-card:nth-child(14n + 9) .pod-card-main,
html[data-theme] #homeRecommended .pod-card:nth-child(14n + 10) .pod-card-main,
html[data-theme] #homeRecommended .pod-card:nth-child(14n + 11) .pod-card-main,
html[data-theme] #homeRecommended .pod-card:nth-child(14n + 12) .pod-card-main { padding: 10px 10px 11px; }
html[data-theme] #homeRecommended .pod-card:nth-child(14n + 7) .pod-card-main > strong,
html[data-theme] #homeRecommended .pod-card:nth-child(14n + 9) .pod-card-main > strong,
html[data-theme] #homeRecommended .pod-card:nth-child(14n + 10) .pod-card-main > strong,
html[data-theme] #homeRecommended .pod-card:nth-child(14n + 11) .pod-card-main > strong,
html[data-theme] #homeRecommended .pod-card:nth-child(14n + 12) .pod-card-main > strong { font-size: clamp(21px, 1.7vw, 24px); }
html[data-theme] #homeRecommended .pod-card:nth-child(14n + 7) .pod-meta,
html[data-theme] #homeRecommended .pod-card:nth-child(14n + 9) .pod-meta,
html[data-theme] #homeRecommended .pod-card:nth-child(14n + 10) .pod-meta,
html[data-theme] #homeRecommended .pod-card:nth-child(14n + 11) .pod-meta,
html[data-theme] #homeRecommended .pod-card:nth-child(14n + 12) .pod-meta { font-size: 10px; }

/* 4×4 与 6×4 大块：字撑起来 */
html[data-theme] #homeRecommended .pod-card:nth-child(14n + 6) .pod-card-main > strong { font-size: clamp(24px, 2.4vw, 38px); -webkit-line-clamp: 3; }
html[data-theme] #homeRecommended .pod-card:nth-child(14n + 2) .pod-card-main > strong { font-size: clamp(26px, 2.6vw, 46px); -webkit-line-clamp: 3; }
html[data-theme] #homeRecommended .pod-card:nth-child(14n + 5) .pod-card-main > strong { font-size: clamp(20px, 2vw, 30px); }
html[data-theme] #homeRecommended .pod-card:nth-child(14n + 13) .pod-card-main > strong,
html[data-theme] #homeRecommended .pod-card:nth-child(14n + 14) .pod-card-main > strong { font-size: clamp(26px, 2.6vw, 46px); -webkit-line-clamp: 3; }
/* 无限补块是按源码变体重新分槽的（槽位尺寸不再跟 nth-child 周期对应），字号改看实际格数 */
html[data-theme] #page-home #homeRecommended .pod-card[data-tile="big"] .pod-card-main > strong {
  font-size: clamp(24px, 2.4vw, 44px);
  -webkit-line-clamp: 3;
}
html[data-theme] #page-home #homeRecommended .pod-card[data-tile="small"] .pod-card-main {
  padding: 10px 10px 11px;
}
html[data-theme] #page-home #homeRecommended .pod-card[data-tile="small"] .pod-card-main > strong {
  font-size: clamp(21px, 1.7vw, 24px);
  -webkit-line-clamp: 2;
}
html[data-theme] #page-home #homeRecommended .pod-card[data-tile="small"] .pod-meta { font-size: 10px; }
/* Folia 的悬浮快钮：指针停在瓦片上，右上角浮出 40px 玻璃圆钮 */
html[data-theme] #homeRecommended .pod-card .pod-actions {
  display: flex !important;
  position: absolute;
  z-index: 4;
  top: 14px;
  right: 14px;
  gap: 6px;
  opacity: 0;
  pointer-events: none;
  transform: translateY(-4px);
  transition: opacity var(--motion-normal) var(--ease), transform var(--motion-normal) var(--ease);
}
html[data-theme] #homeRecommended .pod-card:hover .pod-actions,
html[data-theme] #homeRecommended .pod-card:focus-within .pod-actions {
  opacity: 1;
  pointer-events: auto;
  transform: translateY(0);
}
html[data-theme] #homeRecommended .pod-card .pod-actions .btn {
  position: relative;
  width: 36px;
  height: 36px;
  padding: 0;
