}
html[data-theme] #homeRecommended .pod-card .pod-actions .btn:hover { background: var(--accent); border-color: var(--accent); }
html[data-theme] #homeRecommended .pod-card .pod-actions .btn:active { scale: 0.92; }
html[data-theme] #homeRecommended .pod-card .pod-actions .btn::after {
  content: "＋";
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font: 700 16px/1 var(--sans);
  letter-spacing: 0;
  transform: translateY(-0.5px);   /* 全角＋的基线偏下，光学上提半像素 */
}
/* 墙上每张卡都是已订阅：快钮不该再显示“＋”（那是“加入”的意思）。
   内置节目给对勾（管理中），站外节目给箭头（进入节目页）。 */
