}
html[data-theme] #page-home #homeRecommended .pod-card.is-peek .pod-card-main > strong,
html[data-theme] #page-home #homeRecommended .pod-card.is-playing-tile .pod-card-main > strong {
  font-size: clamp(30px, 3vw, 52px);
  -webkit-line-clamp: 3;
}
html[data-theme] #page-home #homeRecommended .pod-card.is-peek .pod-meta,
html[data-theme] #page-home #homeRecommended .pod-card.is-playing-tile .pod-meta { font-size: 14px; }
/* 尺寸补间时把这张卡的内部布局/样式隔离开：每帧只重排它自己，不牵动 168 张卡 */
html[data-theme] #homeRecommended .pod-card.is-peek {
  contain: layout style;
  will-change: width, height;
}

/* 展开后的底部动作条：进入节目页 / 收起 */
html[data-theme] #homeRecommended .tile-peek {
  position: absolute;
  z-index: 5;
  left: 0;
  right: 0;
  bottom: 0;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 22px 20px;
  opacity: 0;
  transform: translateY(6px);
  pointer-events: none;
  transition: opacity var(--motion-normal) var(--ease), transform var(--motion-normal) var(--ease);
}
html[data-theme] #homeRecommended .pod-card.is-peek .tile-peek { opacity: 1; transform: none; pointer-events: auto; }
html[data-theme] #homeRecommended .tile-peek-kicker {
  margin-right: auto;
  font: 700 11px/1 var(--sans);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(247, 244, 238, 0.6);
}
html[data-theme] #homeRecommended .tile-peek-actions { display: flex; gap: 6px; }
html[data-theme] #homeRecommended .tile-peek-btn {
  appearance: none;
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 999px;
  padding: 9px 14px;
  /* 这四颗按钮挂在会改尺寸的瓦片上：backdrop-filter 每帧都要重算底图，实测把 180Hz 打成 100fps。用实底替代。 */
  background: rgba(8, 8, 10, 0.78);
  color: var(--ink);
  font: 700 12px/1 var(--sans);
  text-decoration: none;
  cursor: pointer;
  transition: background-color var(--motion-normal) var(--ease), border-color var(--motion-normal) var(--ease),
    color var(--motion-normal) var(--ease), transform var(--motion-normal) var(--ease), scale var(--motion-fast) var(--ease);
}
html[data-theme] #homeRecommended .tile-peek-btn:hover { transform: translateY(-1px); background: rgba(255, 255, 255, 0.14); }
html[data-theme] #homeRecommended .tile-peek-btn:active { scale: 0.96; }
html[data-theme] #homeRecommended .tile-peek-btn.primary:hover { background: #ff7a64; border-color: #ff7a64; }
html[data-theme] #homeRecommended .tile-peek-btn.primary {
  background: var(--accent);
  border-color: var(--accent);
  color: #0a0a0a;
}

/* 正在播放的瓦片压当前句（Folia 播放态瓦片就是一块“正在发生的歌词板”） */
html[data-theme] #homeRecommended .tile-live-lyric {
  position: absolute;
  z-index: 4;
  left: 24px;
  right: 24px;
  bottom: 42px;
  display: none;
  font: 650 clamp(15px, 1.4vw, 20px)/1.28 var(--sans);
  color: rgba(255, 255, 255, 0.92);
  text-wrap: balance;
  overflow: hidden;
  pointer-events: none;
}
html[data-theme] #homeRecommended .pod-card.is-playing-tile .tile-live-lyric {
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  gap: 0.55em;
  top: 5%;                /* 字幕区占封面约 2/3，但文字贴着这条区域的底边排 */
  bottom: 30%;            /* 给底部的大标题留出位置，三行字幕不压字 */
  font-family: var(--sans);
  font-weight: 650;
  font-size: clamp(18px, 1.7vw, 26px);
  line-height: 1.3;
  text-shadow: 0 2px 18px rgba(0, 0, 0, 0.66);
}
/* 三行字幕同字号：只靠明暗和字重分主次，不再把上一句/下一句缩成小字。 */
html[data-theme] #homeRecommended .tile-live-lyric .tl-line {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
  transition: opacity var(--motion-slow) var(--ease);
}
html[data-theme] #homeRecommended .tile-live-lyric .tl-prev,
html[data-theme] #homeRecommended .tile-live-lyric .tl-next {
  font-size: 1em;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.44);
}
html[data-theme] #homeRecommended .tile-live-lyric .tl-cur {
  font-weight: 700;
  color: rgba(255, 255, 255, 0.96);
}
/* 播放态的封面保持放大（不随上一条的 hover 收镜） */
html[data-theme] #homeRecommended .pod-card.is-playing-tile .pod-art img {
  transform: scale(1.07);
}
/* 播放态瓦片的版面是“封面 + 大字标题 + 当前句”：标题往上收，歌词独占底部一条 */
html[data-theme] #page-home #homeRecommended .pod-card.is-playing-tile .pod-card-main { padding: 26px 26px 112px; }
html[data-theme] #page-home #homeRecommended .pod-card.is-playing-tile .pod-card-main > strong {
  font-size: clamp(22px, 2.2vw, 36px);
  -webkit-line-clamp: 2;
}
html[data-theme] #page-home #homeRecommended .pod-card.is-playing-tile .pod-meta { display: none; }
html[data-theme] #homeRecommended .pod-card.is-playing-tile .pod-card-main::after { bottom: 16px; right: 16px; }

html[data-theme] .pod-card:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}
/* 方向键选中的瓦片：和鼠标悬停分开，键盘在墙上走位时始终有一个明确的落点。 */
html[data-theme] #homeRecommended .pod-card.is-cursor {
