  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.25);
}
html[data-theme] #homeRecommended .pod-card.is-cursor .pod-card-main > strong { color: var(--bright); }

/* ---------- 5. 播放条：悬浮胶囊 ---------- */
/* ---------- 5. 播放条：默认缩成小胶囊，悬停或播放页才展开 ---------- */
/* 基础层 `body:not(.player-open) .dock{display:none!important}` 会把底栏从墙页拿走；
   Folia 的墙上是常驻迷你播放条，这里把它请回来（播放页照旧展开） */
html[data-theme] body:not(.player-open) .dock { display: block !important; }
/* 播放页（含精听/字幕页）基础层会把底栏拉成通栏并清掉 translate，只剩 left:50% → 整条右移半个身位被切掉。
   这里把播放页也钉回“居中胶囊”，translate 显式写上，不再依赖基础层的居中。 */
html[data-theme] body.player-open .dock {
  left: 50%;
  right: auto;
  bottom: 18px;
  width: min(760px, calc(100vw - 48px));
  max-width: none;
  border: 1px solid var(--folia-glass-line);
  border-radius: 26px;
  translate: -50% 0;
}
html[data-theme] .dock {
  position: fixed;
  left: 50%;
  bottom: 18px;
  translate: -50% 0;
  width: min(760px, calc(100vw - 140px));
  padding: 10px 16px 12px;
  border: 1px solid var(--folia-glass-line);
  border-radius: 24px;
  /* 和搜索胶囊、侧栏同一层烟熏玻璃；展开只动宽度，模糊层跟着几何自适应。 */
  background: var(--folia-glass);
  backdrop-filter: var(--folia-glass-blur);
  -webkit-backdrop-filter: var(--folia-glass-blur);
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.60), 0 0 0 1px rgba(253, 92, 71, 0.08), inset 0 1px 0 rgba(255, 255, 255, 0.09);
  overflow: hidden;
  will-change: width;
  transition: width var(--motion-slow) cubic-bezier(0.2, 0.9, 0.2, 1),
    translate var(--motion-normal) var(--ease),
    box-shadow var(--motion-normal) var(--ease);
}
/* 缩小态：只有封面、标题和播放键，宽 260px 的圆角胶囊 */
html[data-theme] body:not(.player-open) .dock:not(:hover):not(:focus-within) {
  width: 260px;
  padding: 7px 9px 7px 7px;
  border-radius: 26px;
  background: var(--folia-glass);
  box-shadow: 0 18px 46px rgba(0, 0, 0, 0.54), 0 0 0 1px rgba(253, 92, 71, 0.10), inset 0 1px 0 rgba(255, 255, 255, 0.07);
}
html[data-theme] body:not(.player-open) .dock:hover,
html[data-theme] body:not(.player-open) .dock:focus-within {
  translate: -50% -2px;
  box-shadow: 0 34px 88px rgba(0, 0, 0, 0.68), 0 0 0 1px rgba(253, 92, 71, 0.14), inset 0 1px 0 rgba(255, 255, 255, 0.10);
}
html[data-theme] body:not(.player-open) .dock:not(:hover):not(:focus-within) .pbar,
html[data-theme] body:not(.player-open) .dock:not(:hover):not(:focus-within) .deck-lab,
html[data-theme] body:not(.player-open) .dock:not(:hover):not(:focus-within) .epstep,
html[data-theme] body:not(.player-open) .dock:not(:hover):not(:focus-within) .skipbtn,
html[data-theme] body:not(.player-open) .dock:not(:hover):not(:focus-within) .dockquick,
html[data-theme] body:not(.player-open) .dock:not(:hover):not(:focus-within) .docktools,
html[data-theme] body:not(.player-open) .dock:not(:hover):not(:focus-within) .pmeta {
  display: none;
}
html[data-theme] body:not(.player-open) .dock:not(:hover):not(:focus-within) .dockrow {
  gap: 8px;
}
html[data-theme] body:not(.player-open) .dock:not(:hover):not(:focus-within) .nowplay {
  flex: 1;
  min-width: 0;
}
html[data-theme] body:not(.player-open) .dock:not(:hover):not(:focus-within) .ptitle {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
html[data-theme] .dock .pbar { height: 3px; margin: 0 0 9px; background: rgba(255, 255, 255, 0.10); border-radius: 999px; }
html[data-theme] .dock .pbar .track { border-radius: 999px; overflow: hidden; }
html[data-theme] .dock .pfill {
  height: 3px;
  border-radius: 999px;
